//! C-alignment regression tests (step H3: index builds, the transfer optimisation, VACUUM, ALTER TABLE RENAME / DROP
//! COLUMN). GENERATED by target/perf-work/h3/gen_tests3.py: every expected value is what C SQLite 3.54.1 produces —
//! size and FNV-1a hash of the database file C writes for the statements (and of the file `VACUUM INTO` writes), the
//! rows and the error messages C returns. The file cases fail with the code of step H2 (own bottom-up index builder,
//! row-by-row copies, own VACUUM image, single-row catalogue updates); nothing here depends on files outside the
//! repository.
use crate::Connection;

fn fnv1a(bytes: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for &b in bytes {
        h = (h ^ u64::from(b)).wrapping_mul(0x0000_0100_0000_01b3);
    }
    h
}

struct TempDb(std::path::PathBuf);

impl TempDb {
    fn new(name: &str) -> Self {
        let path =
            std::env::temp_dir().join(format!("sqliters-h3-{}-{name}.db", std::process::id()));
        let db = Self(path);
        db.remove_all();
        db
    }
    fn into_path(&self) -> std::path::PathBuf {
        let mut s = self.0.clone().into_os_string();
        s.push(".into");
        std::path::PathBuf::from(s)
    }
    fn remove_all(&self) {
        for suffix in ["", "-journal", "-wal", "-shm", ".into", ".into-journal"] {
            let mut s = self.0.clone().into_os_string();
            s.push(suffix);
            let _ = std::fs::remove_file(std::path::PathBuf::from(s));
        }
    }
}

impl Drop for TempDb {
    fn drop(&mut self) {
        self.remove_all();
    }
}

fn assert_files_are_what_c_writes(
    name: &str,
    stmts: &[&str],
    c_size: usize,
    c_hash: u64,
    c_into: Option<(usize, u64)>,
) {
    let db = TempDb::new(name);
    let into = db.into_path();
    let conn = Connection::open(&db.0).unwrap();
    for sql in stmts {
        let sql = sql.replace("@INTO@", &into.to_string_lossy());
        // (a statement may fail, as it does in the C shell that produced the expected file:
        // the script goes on)
        let _ = conn.query(&sql, &[]);
    }
    assert!(conn.try_close().is_ok());
    let bytes = std::fs::read(&db.0).unwrap();
    assert_eq!(bytes.len(), c_size, "{name}: file size");
    assert_eq!(fnv1a(&bytes), c_hash, "{name}: file content differs from C");
    if let Some((size, hash)) = c_into {
        let bytes = std::fs::read(&into).unwrap();
        assert_eq!(bytes.len(), size, "{name}: size of the VACUUM INTO file");
        assert_eq!(
            fnv1a(&bytes),
            hash,
            "{name}: VACUUM INTO file differs from C"
        );
    }
}

/// Runs the statements; `c_out` is what the C shell prints for them (rows as `a|b`, one per line), `c_errors` the
/// messages of the statements that fail, in order.
fn assert_rows_and_errors_are_what_c_returns(
    name: &str,
    stmts: &[&str],
    c_out: &str,
    c_errors: &[&str],
) {
    let db = TempDb::new(name);
    let into = db.into_path();
    let conn = Connection::open(&db.0).unwrap();
    let mut out = String::new();
    let mut errors: Vec<String> = Vec::new();
    for sql in stmts {
        let sql = sql.replace("@INTO@", &into.to_string_lossy());
        match conn.query(&sql, &[]) {
            Ok(res) => {
                for row in &res.rows {
                    let cells: Vec<String> = row
                        .values
                        .iter()
                        .map(|v| match v {
                            sqliters_types::Value::Null => String::new(),
                            sqliters_types::Value::Integer(i) => i.to_string(),
                            sqliters_types::Value::Real(r) => format!("{r:?}"),
                            sqliters_types::Value::Text(s) => s.to_string(),
                            sqliters_types::Value::Blob(b) => {
                                String::from_utf8_lossy(&b[..]).into_owned()
                            }
                        })
                        .collect();
                    out.push_str(&cells.join("|"));
                    out.push('\n');
                }
            }
            Err(e) => errors.push(e.message.clone()),
        }
    }
    assert!(conn.try_close().is_ok());
    assert_eq!(out, c_out, "{name}: rows");
    assert_eq!(errors, c_errors, "{name}: error messages");
}

/// `CREATE INDEX` (`sqlite3RefillIndex`): the catalogue row is written before the fill; the keys leave the sorter ordered on the key columns with equal keys in rowid order and are appended through a `BTREE_BULKLOAD` cursor (`OP_SeekEnd`, `OP_IdxInsert` with `OPFLAG_USESEEKRESULT`), which leaves the left siblings packed (`balance_nonroot(bBulk=1)`).
#[test]
fn create_index_sorter_then_bulk_append_1024() {
    assert_files_are_what_c_writes(
        "create_index_sorter_then_bulk_append_1024",
        &[
            "PRAGMA page_size=1024;",
            "CREATE TABLE t(id INTEGER PRIMARY KEY, a TEXT, b INT, c);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<2500) INSERT INTO t SELECT x, printf('%0*d', 10 + (x*7919)%50, (x*31)%1009), (x*104729)%10007, CASE WHEN x%7=0 THEN NULL WHEN x%3=0 THEN x*1.5 ELSE 'v'||(x%97) END FROM c;",
            "CREATE INDEX ta ON t(a);",
            "CREATE INDEX tb ON t(b, a);",
            "CREATE INDEX tc ON t(c);",
            "CREATE UNIQUE INDEX tu ON t(b, id);",
        ],
        428032,
        0xf76748b221b665a7,
        None,
    );
}

/// index build over expression, partial, DESC and NOCASE / RTRIM keys, and keys that spill to overflow pages; a UNIQUE build that finds a duplicate aborts with the keys before it inserted and leaves no trace.
#[test]
fn create_index_expression_partial_desc_collation_512() {
    assert_files_are_what_c_writes(
        "create_index_expression_partial_desc_collation_512",
        &[
            "PRAGMA page_size=512;",
            "CREATE TABLE t(id INTEGER PRIMARY KEY, a TEXT, b TEXT COLLATE NOCASE, c);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<900) INSERT INTO t SELECT x, printf('%0*d', 10 + (x*7919)%50, (x*31)%1009), CASE x%2 WHEN 0 THEN 'Key' ELSE 'kEY' END||(x%55), CASE WHEN x%9=0 THEN zeroblob((x*7919)%1500) ELSE 'r'||(x%30)||substr('      ',1,x%5) END FROM c;",
            "CREATE INDEX e1 ON t(length(a), b);",
            "CREATE INDEX p1 ON t(a) WHERE id%2=0;",
            "CREATE INDEX d1 ON t(b DESC, a);",
            "CREATE INDEX c1 ON t(c COLLATE RTRIM);",
            "CREATE UNIQUE INDEX u1 ON t(b);",
            "CREATE INDEX c2 ON t(c);",
        ],
        433664,
        0x7c23a33271d249b4,
        None,
    );
}

/// index keys of REAL columns are taken in the form the table stores them (`sqlite3GenerateIndexKey` drops the `OP_RealAffinity`), also when the table has a VIRTUAL column, a DEFAULT or the index is partial.
#[test]
fn create_index_keeps_stored_form_of_real_columns_1024() {
    assert_files_are_what_c_writes(
        "create_index_keeps_stored_form_of_real_columns_1024",
        &[
            "PRAGMA page_size=1024;",
            "CREATE TABLE t(id INTEGER PRIMARY KEY, a REAL, b INT, g AS (b*2) STORED, v AS (a+b) VIRTUAL, d REAL DEFAULT 7);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<1200) INSERT INTO t(id,a,b) SELECT x, CASE WHEN x%2=0 THEN x ELSE x+0.5 END, x%300 FROM c;",
            "CREATE INDEX ta ON t(a);",
            "CREATE INDEX tg ON t(g, a);",
            "CREATE INDEX tv ON t(v);",
            "CREATE INDEX tp ON t(d, a) WHERE b>5;",
        ],
        105472,
        0xcec2e203a2689ca6,
        None,
    );
}

/// `REINDEX` (3.54 `sqlite3Reindex`): one walk over the tables in hash order and their indexes newest first; `OP_Clear`, then the sorter fill; a collation name selects every index with a column of that collation (the rowid counts as BINARY), `expressions` every expression index.
#[test]
fn reindex_forms_and_order_1024() {
    assert_files_are_what_c_writes(
        "reindex_forms_and_order_1024",
        &[
            "PRAGMA page_size=1024;",
            "CREATE TABLE t(id INTEGER PRIMARY KEY, a TEXT COLLATE NOCASE, b INT, c TEXT);",
            "CREATE INDEX ta ON t(a);",
            "CREATE INDEX tb ON t(b);",
            "CREATE UNIQUE INDEX tc ON t(c);",
            "CREATE INDEX te ON t(length(c));",
            "CREATE TABLE u(x TEXT PRIMARY KEY, y UNIQUE, z) WITHOUT ROWID;",
            "CREATE INDEX uz ON u(z COLLATE NOCASE);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<1200) INSERT INTO t SELECT x, printf('%0*d', 10 + (x*7919)%50, (x*31)%1009), (x*104729)%10007, 'c'||x FROM c;",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<700) INSERT INTO u SELECT printf('%05d', (x*7919)%10007), x, 'Z'||(x%60) FROM c;",
            "DELETE FROM t WHERE id%5=0;",
            "REINDEX nocase;",
            "REINDEX expressions;",
            "REINDEX tb;",
            "REINDEX u;",
            "REINDEX;",
        ],
        208896,
        0xc96b2dad73aa8f2a,
        None,
    );
}

/// `INSERT INTO d SELECT * FROM s` (`xferOptimization`): rows are copied cell by cell (`OP_RowCell`, `OPFLAG_PREFORMAT`: overflow pages allocated with nearby=0), then every index entry by entry through a bulk cursor.
#[test]
fn transfer_copy_into_empty_table_with_indexes_1024() {
    assert_files_are_what_c_writes(
        "transfer_copy_into_empty_table_with_indexes_1024",
        &[
            "PRAGMA page_size=1024;",
            "CREATE TABLE s(id INTEGER PRIMARY KEY, a TEXT, b);",
            "CREATE INDEX sa ON s(a);",
            "CREATE INDEX sb ON s(b);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<1500) INSERT INTO s SELECT x, printf('%0*d', 10 + (x*7919)%50, (x*31)%1009), CASE WHEN x%40=0 THEN zeroblob((x*7919)%3000) ELSE (x*104729)%10007 END FROM c;",
            "DELETE FROM s WHERE id%6=0;",
            "CREATE TABLE d(id INTEGER PRIMARY KEY, a TEXT, b);",
            "CREATE INDEX da ON d(a);",
            "CREATE INDEX db ON d(b);",
            "INSERT INTO d SELECT * FROM s;",
        ],
        491520,
        0xba8e95ed7cc27da1,
        None,
    );
}

/// transfer into a table without INTEGER PRIMARY KEY and without index gives the rows new rowids (`OP_NewRowid`); into a non-empty table with INTEGER PRIMARY KEY every rowid is looked up first; a destination with a UNIQUE index takes the transfer only when it is empty.
#[test]
fn transfer_copy_new_rowids_and_non_empty_destination_512() {
    assert_files_are_what_c_writes(
        "transfer_copy_new_rowids_and_non_empty_destination_512",
        &[
            "PRAGMA page_size=512;",
            "CREATE TABLE s(a TEXT, b INT);",
            "CREATE TABLE d(a TEXT, b INT);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<600) INSERT INTO s(rowid,a,b) SELECT x*3, printf('%0*d', 10 + (x*7919)%50, (x*31)%1009), x FROM c;",
            "INSERT INTO d SELECT * FROM s;",
            "INSERT INTO d SELECT * FROM s;",
            "CREATE TABLE s2(id INTEGER PRIMARY KEY, a TEXT UNIQUE);",
            "CREATE TABLE d2(id INTEGER PRIMARY KEY, a TEXT UNIQUE);",
            "INSERT INTO s2 SELECT rowid, a||rowid FROM s;",
            "INSERT INTO d2 SELECT * FROM s2;",
            "CREATE TABLE s3(id INTEGER PRIMARY KEY, a);",
            "CREATE TABLE d3(id INTEGER PRIMARY KEY, a);",
            "INSERT INTO d3 VALUES(100000,'pre');",
            "INSERT INTO s3 SELECT rowid, a FROM s;",
            "INSERT INTO d3 SELECT * FROM s3;",
        ],
        268800,
        0xe0c2a44d005b42ba,
        None,
    );
}

/// `VACUUM` (`sqlite3RunVacuum`): the CREATE TABLE statements run first (automatic indexes and sqlite_sequence with them), then the CREATE INDEX statements, then every table of the new catalogue is filled by the transfer optimisation (appends; new rowids for a table without INTEGER PRIMARY KEY and without index), then the view / trigger rows are copied, then the meta values.
#[test]
fn vacuum_every_object_kind_1024() {
    assert_files_are_what_c_writes(
        "vacuum_every_object_kind_1024",
        &[
            "PRAGMA page_size=1024;",
            "CREATE TABLE t(id INTEGER PRIMARY KEY, a TEXT, b INT, c);",
            "CREATE INDEX ta ON t(a);",
            "CREATE INDEX tb ON t(b DESC, a);",
            "CREATE INDEX tn ON t(a COLLATE NOCASE);",
            "CREATE INDEX tp ON t(b) WHERE b%2=0;",
            "CREATE TABLE plain(a, b);",
            "CREATE TABLE plidx(a, b);",
            "CREATE INDEX plidxa ON plidx(a);",
            "CREATE TABLE wr(k TEXT, n INT, v, PRIMARY KEY(k, n)) WITHOUT ROWID;",
            "CREATE INDEX wrv ON wr(v);",
            "CREATE TABLE ai(id INTEGER PRIMARY KEY AUTOINCREMENT, a UNIQUE, b UNIQUE ON CONFLICT REPLACE);",
            "CREATE TABLE big(id INTEGER PRIMARY KEY, z);",
            "CREATE VIEW vw AS SELECT a, b FROM t WHERE b>10;",
            "CREATE TRIGGER trg AFTER INSERT ON plain BEGIN UPDATE plidx SET b=b+1 WHERE a=new.a; END;",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<900) INSERT INTO t SELECT x, printf('%0*d', 10 + (x*7919)%50, (x*31)%1009), (x*104729)%10007, CASE WHEN x%7=0 THEN NULL WHEN x%3=0 THEN x*1.5 ELSE 'v'||(x%97) END FROM c;",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<300) INSERT INTO plain(rowid,a,b) SELECT x*5, 'p'||x, x FROM c;",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<300) INSERT INTO plidx(rowid,a,b) SELECT x*7, printf('%0*d', 10 + (x*7919)%50, (x*31)%1009), x FROM c;",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<300) INSERT INTO wr SELECT printf('%05d', (x*7919)%1009), x, printf('%0*d', 10 + (x*7919)%50, (x*31)%1009) FROM c;",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<150) INSERT INTO ai(a,b) SELECT 'a'||x, -x FROM c;",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<50) INSERT INTO big SELECT x, zeroblob((x*7919)%9000) FROM c;",
            "DELETE FROM t WHERE id%3=0;",
            "DELETE FROM plain WHERE rowid%2=0;",
            "DELETE FROM big WHERE id%5=0;",
            "VACUUM;",
        ],
        388096,
        0x9d9a91f3ebe18600,
        None,
    );
}

