/// `ALTER TABLE ... RENAME` (alter.c): the catalogue is rewritten by nested UPDATE statements, each in rowid order — the `sql` texts first, then (table rename) `name` / `tbl_name`; RENAME COLUMN runs `renameFixQuotes` first and its second UPDATE writes integers 0 / 1 the legacy way because the temp schema (file format 1) was opened for writing in between.
#[test]
fn alter_rename_table_and_column_1024() {
    assert_files_are_what_c_writes(
        "alter_rename_table_and_column_1024",
        &[
            "PRAGMA page_size=1024;",
            "CREATE TABLE p(id INTEGER PRIMARY KEY, name TEXT UNIQUE, v INT);",
            "CREATE TABLE c(id INTEGER PRIMARY KEY AUTOINCREMENT, pid INT REFERENCES p(id), note TEXT, FOREIGN KEY(note) REFERENCES p(name));",
            "CREATE INDEX c_pid ON c(pid);",
            "CREATE INDEX p_v ON p(v, name);",
            "CREATE VIEW pv AS SELECT p.id, p.name, c.note FROM p JOIN c ON c.pid=p.id WHERE p.v>0;",
            "CREATE TRIGGER p_ai AFTER INSERT ON p BEGIN INSERT INTO c(pid, note) VALUES(new.id, new.name); END;",
            "CREATE TRIGGER c_au AFTER UPDATE OF note ON c BEGIN UPDATE p SET v=v+1 WHERE id=new.pid; END;",
            "CREATE TABLE other(x, y, z);",
            "CREATE INDEX other_x ON other(x);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<150) INSERT INTO p SELECT x, 'n'||x, x%7 FROM c;",
            "INSERT INTO other SELECT id, v, id%2 FROM p;",
            "ALTER TABLE p RENAME TO parent_table;",
            "ALTER TABLE parent_table RENAME COLUMN name TO full_name;",
            "ALTER TABLE c RENAME COLUMN note TO \"the note\";",
            "ALTER TABLE other RENAME TO o2;",
        ],
        25600,
        0x553e58cb0b3452b1,
        None,
    );
}

/// `ALTER TABLE ... DROP COLUMN`: `renameFixQuotes`, the table row, then every row of the table is rebuilt and stored back at the cursor (`OPFLAG_SAVEPOSITION`), integers 0 / 1 as one-byte integers (`Vdbe.minWriteFileFormat` lowered by the write cursor on the temp schema); a WITHOUT ROWID table is not cleared first.
#[test]
fn alter_drop_column_rewrites_rows_in_place_1024() {
    assert_files_are_what_c_writes(
        "alter_drop_column_rewrites_rows_in_place_1024",
        &[
            "PRAGMA page_size=1024;",
            "CREATE TABLE p(id INTEGER PRIMARY KEY, name TEXT UNIQUE, v INT);",
            "CREATE TABLE c(id INTEGER PRIMARY KEY AUTOINCREMENT, pid INT REFERENCES p(id), note TEXT, FOREIGN KEY(note) REFERENCES p(name));",
            "CREATE INDEX c_pid ON c(pid);",
            "CREATE INDEX p_v ON p(v, name);",
            "CREATE VIEW pv AS SELECT p.id, p.name, c.note FROM p JOIN c ON c.pid=p.id WHERE p.v>0;",
            "CREATE TRIGGER p_ai AFTER INSERT ON p BEGIN INSERT INTO c(pid, note) VALUES(new.id, new.name); END;",
            "CREATE TRIGGER c_au AFTER UPDATE OF note ON c BEGIN UPDATE p SET v=v+1 WHERE id=new.pid; END;",
            "CREATE TABLE other(x, y, z);",
            "CREATE INDEX other_x ON other(x);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<150) INSERT INTO p SELECT x, 'n'||x, x%7 FROM c;",
            "INSERT INTO other SELECT id, v, id%2 FROM p;",
            "ALTER TABLE other DROP COLUMN y;",
            "CREATE TABLE w(k TEXT PRIMARY KEY, a, b, c) WITHOUT ROWID;",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<400) INSERT INTO w SELECT printf('%05d', x), x%2, 'drop'||x, x%3 FROM c;",
            "ALTER TABLE w DROP COLUMN b;",
        ],
        34816,
        0xfbf0f8760202d4ea,
        None,
    );
}

/// several `UNIQUE ... ON CONFLICT REPLACE` constraints: the REPLACE indexes follow the others in the index list newest first (C links a new index at the head and moves it down only past the non-REPLACE ones) — the order the entries are written in.
#[test]
fn unique_replace_constraints_index_order_512() {
    assert_files_are_what_c_writes(
        "unique_replace_constraints_index_order_512",
        &[
            "PRAGMA page_size=512;",
            "CREATE TABLE t(a UNIQUE ON CONFLICT REPLACE, b UNIQUE ON CONFLICT REPLACE, c UNIQUE, d UNIQUE ON CONFLICT REPLACE);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<400) INSERT INTO t SELECT x, x*7%401, x*13%401, x*17%401 FROM c;",
            "INSERT OR REPLACE INTO t SELECT a+3, b, a+1000, d+5 FROM t WHERE a<200;",
            "DELETE FROM t WHERE a%3=0;",
        ],
        28160,
        0x5773f5903ed7cd7f,
        None,
    );
}

/// `INSERT OR REPLACE ... SELECT` into a table without index: after a row was replaced where it was, `OP_NotExists` reaches the row with the next rowid through `sqlite3BtreeNext` (`sqlite3BtreeTableMoveto`: "the requested key is one more than the previous key"), which parses its cell, so a record of the same size is written over the old one and its overflow chain is kept (`btreeOverwriteCell`); the first row of the statement, a row after a gap and every row of a new statement (trigger step) are replaced cell by cell instead; the same holds for the second pass of an UPDATE that reads no old column.
#[test]
fn replace_select_over_consecutive_rowids_overwrites_1024() {
    assert_files_are_what_c_writes(
        "replace_select_over_consecutive_rowids_overwrites_1024",
        &[
            "PRAGMA page_size=1024;",
            "CREATE TABLE s(id INTEGER PRIMARY KEY, k, a);",
            "CREATE TABLE d(id INTEGER PRIMARY KEY, k, a);",
            "CREATE TABLE e(id INTEGER PRIMARY KEY, k, a);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<120) INSERT INTO s SELECT x, x%7, printf('%0*d', CASE WHEN x%4=0 THEN 2500+x%3*1100 ELSE 20+x%90 END, x) FROM c;",
            "INSERT INTO d SELECT * FROM s;",
            "INSERT INTO e SELECT * FROM s;",
            "INSERT OR REPLACE INTO d SELECT id, k+1, a FROM s WHERE id%10<>0;",
            "CREATE TRIGGER tr AFTER INSERT ON d WHEN new.id%8=0 BEGIN INSERT OR REPLACE INTO e SELECT id, 9, a FROM s WHERE id BETWEEN new.id AND new.id+5; INSERT OR REPLACE INTO e SELECT id, 8, a FROM s WHERE id=new.id+6; END;",
            "INSERT OR REPLACE INTO d SELECT id, k+2, a FROM s WHERE id>30;",
            "DROP TRIGGER tr;",
            "UPDATE d SET k=5, a=printf('%03600d', 7) WHERE id IN (SELECT id FROM s WHERE id%4=0 AND id>60);",
            "UPDATE d SET k=6, a=printf('%03600d', 8) WHERE id IN (SELECT id FROM s WHERE id BETWEEN 70 AND 110);",
            "UPDATE d SET k=6, a=printf('%03600d', 9) WHERE id IN (SELECT id FROM s WHERE id BETWEEN 70 AND 110);",
        ],
        502784,
        0x97234cf9e1f59e9d,
        None,
    );
}

/// what the transfer optimisation shows through SQL: new rowids for a table without INTEGER PRIMARY KEY and without index, kept rowids with an index; with generated columns the statement only compiles when the transfer is certain (no UNIQUE index on the destination).
#[test]
fn transfer_semantics_rows() {
    assert_rows_and_errors_are_what_c_returns(
        "transfer_semantics_rows",
        &[
            "CREATE TABLE s(a);",
            "INSERT INTO s(rowid,a) VALUES(5,'x'),(10,'y');",
            "CREATE TABLE d(a);",
            "INSERT INTO d SELECT * FROM s;",
            "SELECT rowid, a FROM d;",
            "CREATE TABLE s2(a);",
            "CREATE INDEX s2a ON s2(a);",
            "CREATE TABLE d2(a);",
            "CREATE INDEX d2a ON d2(a);",
            "INSERT INTO s2(rowid,a) SELECT rowid,a FROM s;",
            "INSERT INTO d2 SELECT * FROM s2;",
            "SELECT rowid, a FROM d2;",
            "CREATE TABLE g1(a INTEGER PRIMARY KEY, b AS (a+1), c);",
            "CREATE TABLE g2(a INTEGER PRIMARY KEY, b AS (a+1), c);",
            "INSERT INTO g1 VALUES(1,2);",
            "INSERT INTO g2 SELECT * FROM g1;",
            "SELECT * FROM g2;",
            "CREATE TABLE g3(a, b AS (a+1), c UNIQUE);",
            "CREATE TABLE g4(a, b AS (a+1), c UNIQUE);",
            "INSERT INTO g3 VALUES(1,2);",
            "INSERT INTO g4 SELECT * FROM g3;",
            "SELECT count(*) FROM g4;",
        ],
        "1|x\n2|y\n5|x\n10|y\n1|2|2\n0\n",
        &["table g4 has 2 columns but 3 values were supplied"],
    );
}

/// a UNIQUE index build over duplicate keys fails with the constraint message of the index columns (expression index: its name); NULLs never collide; the failed statement leaves nothing behind.
#[test]
fn create_unique_index_reports_the_duplicate() {
    assert_rows_and_errors_are_what_c_returns(
        "create_unique_index_reports_the_duplicate",
        &[
            "CREATE TABLE t(a, b);",
            "INSERT INTO t VALUES(1,1),(2,1),(NULL,2),(NULL,2),(3,3);",
            "CREATE UNIQUE INDEX ua ON t(a);",
            "CREATE UNIQUE INDEX ub ON t(b);",
            "CREATE UNIQUE INDEX uab ON t(b, a);",
            "CREATE UNIQUE INDEX ue ON t(b+0);",
            "SELECT name FROM sqlite_schema ORDER BY name;",
            "PRAGMA integrity_check;",
        ],
        "t\nua\nuab\nok\n",
        &[
            "UNIQUE constraint failed: t.b",
            "UNIQUE constraint failed: index 'ue'",
        ],
    );
}

/// RENAME COLUMN to a name another column has: the catalogue is rewritten, `renameTestSchema` then fails ("error in table ... after rename: duplicate column name") and the statement is rolled back; sqlite_stat1 keeps the old table name on RENAME TO.
#[test]
fn rename_column_to_an_existing_name_fails_after_the_rewrite() {
    assert_rows_and_errors_are_what_c_returns(
        "rename_column_to_an_existing_name_fails_after_the_rewrite",
        &[
            "CREATE TABLE t(a UNIQUE, b);",
            "CREATE INDEX tb ON t(b);",
            "INSERT INTO t VALUES(1,2),(3,4);",
            "ANALYZE;",
            "ALTER TABLE t RENAME COLUMN a TO b;",
            "SELECT sql FROM sqlite_schema WHERE name='t';",
            "ALTER TABLE t RENAME TO u;",
            "SELECT tbl, idx FROM sqlite_stat1 ORDER BY 1, 2;",
            "PRAGMA integrity_check;",
        ],
        "CREATE TABLE t(a UNIQUE, b)\nt|sqlite_autoindex_t_1\nt|tb\nok\n",
        &["error in table t after rename: duplicate column name: b"],
    );
}

/// `REINDEX` accepts `expressions`, a collation, a table, an index; anything else is "unable to identify the object to be reindexed".
#[test]
fn reindex_names() {
    assert_rows_and_errors_are_what_c_returns(
        "reindex_names",
        &[
            "CREATE TABLE t(a COLLATE NOCASE, b);",
            "CREATE INDEX ta ON t(a);",
            "CREATE INDEX te ON t(b+1);",
            "INSERT INTO t VALUES('x',1),('X',2);",
            "REINDEX expressions;",
            "REINDEX nocase;",
            "REINDEX binary;",
            "REINDEX t;",
            "REINDEX main.ta;",
            "REINDEX nosuch;",
            "SELECT count(*) FROM t INDEXED BY ta WHERE a='x';",
        ],
        "2\n",
        &["unable to identify the object to be reindexed"],
    );
}

/// a database file created by ATTACH gets the library default page size, whatever `PRAGMA page_size` the main database was given.
#[test]
fn attach_creates_a_file_with_the_default_page_size() {
    assert_rows_and_errors_are_what_c_returns(
        "attach_creates_a_file_with_the_default_page_size",
        &[
            "PRAGMA page_size=1024;",
            "CREATE TABLE t(a);",
            "ATTACH '@INTO@' AS aux;",
            "CREATE TABLE aux.u(a);",
            "PRAGMA main.page_size;",
            "PRAGMA aux.page_size;",
        ],
        "1024\n4096\n",
        &[],
    );
}
